async () => {
  const w = document.querySelector('iframe').contentWindow;
  const app = w.pc.Application.getApplication();
  const st = w.ConfiguratorAPI.getSelectTool();
  const sinks = [];
  app.root.forEach((e) => { if (/sink_?point$/i.test(e.name) && e.enabled) sinks.push(e); });
  if (!sinks.length) return { err: 'no sink point' };
  const ren = []; sinks[0].forEach((e) => { if (e.enabled && e.render?.enabled) ren.push(e); });
  const pick = ren[0] || sinks[0];
  st.setSelected([pick]);
  await new Promise((r) => setTimeout(r, 800));
  const info = JSON.parse(JSON.stringify(w.ConfiguratorAPI.getSelectionInfo() || []));
  const pid = (Array.isArray(info) ? info[0] : info)?.productId;
  const cfg = pid ? await w.ConfiguratorAPI.getConfig(pid) : null;
  const pickCfg = (c) => c && Object.fromEntries(Object.entries(c.config ?? c).filter(([k]) => /sink|vessel|countertop/i.test(k)));
  window.__qaVesselPid = pid; return { sinkPoints: sinks.map((s) => s.name), picked: pick.name, info, productId: pid, config: pickCfg(cfg) };
}

async () => {
  const w = document.querySelector('iframe').contentWindow;
